with enriched as (select *, sum(quantity) over (partition by order_id, product_id order by unit_price, id rows between unbounded preceding and current row) running_sum_quantity, avg(quantity) over (partition by order_id, product_id order by unit_price, id rows between unbounded preceding and current row) running_avg_quantity, min(quantity) over (partition by order_id, product_id order by unit_price, id rows between unbounded preceding and current row) running_min_quantity from order_items where product_id is null) select s.id, s.order_id, s.quantity, s.unit_price, s.running_min_quantity, (select min(x.amount) from payments x where x.order_id = s.order_id) as min_payment_amount from enriched s;
